const localInstant=(day:string,time:string,timezone='Asia/Kolkata')=>{const [year,month,dateValue]=day.split('-').map(Number),[hour,minute]=time.split(':').map(Number),target=Date.UTC(year!,month!-1,dateValue!,hour!,minute!);let guess=target;for(let i=0;i<3;i++){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:timezone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(guess)).filter(part=>part.type!=='literal').map(part=>[part.type,Number(part.value)])),seen=Date.UTC(parts.year!,parts.month!-1,parts.day!,parts.hour!,parts.minute!);guess+=target-seen;}return new Date(guess);};

