async function signIn(page:Page,email:string,password:string,workspace:'leadership'|'admin') {const target=`/${workspace==='leadership'?'leadership':'admin'}`,choice=workspace==='leadership'?'leadership':'administration';page.setDefaultTimeout(30000);await page.goto('/sign-in');await page.getByLabel('Email address').fill(email);await page.getByLabel(/^Password/).fill(password);await page.getByRole('button',{name:'Sign in',exact:true}).click();await page.waitForURL(url=>url.pathname==='/choose-workspace'||url.pathname===target);if(new URL(page.url()).pathname==='/choose-workspace'){const branch=page.getByRole('combobox',{name:'Branch'}),settled=await Promise.race([branch.waitFor({state:'visible',timeout:15000}).then(()=> 'chooser' as const),page.waitForURL(url=>url.pathname===target,{timeout:15000}).then(()=> 'target' as const)]);if(settled==='chooser'){await branch.selectOption(`${scope.schoolId}:${choice}`);await page.getByRole('button',{name:/Continue/}).click();await page.getByRole('button',{name:/Confirm/}).click();}}await expect(page).toHaveURL(new RegExp(`${target}$`));}
