 const prepare=async(offset:number)=>{const next=await db.attendanceSession.create({data:{id:randomUUID(),organizationId:scope.organizationId,schoolId:scope.schoolId,offeringId:base.offeringId,schoolDate:base.schoolDate,startsAt:new Date(base.startsAt.getTime()+offset*3_600_000),endsAt:new Date(base.endsAt.getTime()+offset*3_600_000),occurrenceKey:`DECISION-RECOVERY-${offset}-${randomUUID()}`,calendarRevisionId:base.calendarRevisionId,status:'SCHEDULED',version:1,stateUpdatedAt:base.stateUpdatedAt}}),request=await coordination.create(principalIdentity,scope.organizationId,scope.schoolId,{sessionId:next.id,kind:'MISSING_REGISTER',concern:'MISSING_REGISTER',note:null,dueLocal:null,assigneeAccountId:worker.accountId,assignmentReason:'Prepare recovery state evidence',key:randomUUID()}),opened=await coordination.start(worker.identity,scope.organizationId,scope.schoolId,{requestId:request.requestId,expectedVersion:request.version,reason:null,key:randomUUID()}),ready=await coordination.submit(worker.identity,scope.organizationId,scope.schoolId,{requestId:request.requestId,expectedVersion:opened.version,kind:'NO_CHANGE_NEEDED',revision:null,reason:'Recovery state evidence remains owner controlled.',key:randomUUID()});return {request,ready};};
