test('captures approved LEA-09, LEA-11 and LEA-15 reference states unchanged',async({page},testInfo)=>{const reference=pathToFileURL(resolve('docs/execution/VSchool_Execution_Pack/references/approved/packs/VSchool_Principal_Leadership_Workflows/VSchool_Principal_Leadership_Workflows.html')).href,titles={"LEA-09":'Create an accountable missing-register follow-up',"LEA-11":'Verify, close or reopen a follow-up',"LEA-15":'Resolve an incorrect or duplicate scheduled session'} as const;for(const workflow of Object.keys(titles) as (keyof typeof titles)[]){await page.goto(reference);await page.evaluate(id=>{(window as unknown as {WorkflowReview:{read:(value:string)=>void}}).WorkflowReview.read(id);},workflow);const dialog=page.getByRole('dialog');await expect(dialog.getByRole('heading',{name:titles[workflow]})).toBeVisible();await expect(dialog.locator('.tag').filter({hasText:workflow})).toBeVisible();await page.screenshot({path:`${evidence}/reference-${workflow.toLowerCase()}-${testInfo.project.name}.png`,fullPage:true});}});

test('captures the unchanged approved LEA-10 workflow state',async({page},testInfo)=>{const reference=pathToFileURL(resolve('docs/execution/VSchool_Execution_Pack/references/approved/packs/VSchool_Principal_Leadership_Workflows/VSchool_Principal_Leadership_Workflows.html')).href;await page.goto(reference);await page.evaluate(()=>(window as unknown as {WorkflowReview:{read:(value:string)=>void}}).WorkflowReview.read('LEA-10'));const dialog=page.getByRole('dialog');await expect(dialog.getByRole('heading',{name:'Follow up multiple missing registers safely'})).toBeVisible();await page.screenshot({path:`${bulkEvidence}/reference-lea-10-${testInfo.project.name}.png`,fullPage:true});});
